import LibXray
import NetworkExtension

/// Network Extension target (`<app id>.PacketTunnel`). The target is generated by
/// tool/ios_add_tunnel.rb; LibXray.xcframework comes from `tool/fetch_core.sh ios`.
final class PacketTunnelProvider: NEPacketTunnelProvider {
  override func startTunnel(options: [String: NSObject]?, completionHandler: @escaping (Error?) -> Void) {
    guard let config = options?["config"] as? String else {
      return completionHandler(Self.error(1, "No configuration"))
    }
    let settings = NEPacketTunnelNetworkSettings(tunnelRemoteAddress: "127.0.0.1")
    settings.mtu = 1500
    let v4 = NEIPv4Settings(addresses: ["172.19.0.1"], subnetMasks: ["255.255.255.252"])
    v4.includedRoutes = [NEIPv4Route.default()]
    settings.ipv4Settings = v4
    let v6 = NEIPv6Settings(addresses: ["fdfe:dcba:9876::1"], networkPrefixLengths: [126])
    v6.includedRoutes = [NEIPv6Route.default()]
    settings.ipv6Settings = v6
    settings.dnsSettings = NEDNSSettings(servers: ["172.19.0.2"])

    setTunnelNetworkSettings(settings) { [weak self] error in
      guard let self else { return }
      if let error { return completionHandler(error) }
      guard let fd = self.tunnelFd else {
        return completionHandler(Self.error(2, "TUN descriptor not found"))
      }
      let assets = Bundle.main.resourcePath ?? ""
      setenv("XRAY_LOCATION_ASSET", assets, 1)

      // libXray API v3: runtime options go into the config's root `env` object.
      var root = (try? JSONSerialization.jsonObject(with: Data(config.utf8))) as? [String: Any] ?? [:]
      var env = root["env"] as? [String: Any] ?? [:]
      env["xray.tun.fd"] = String(fd)
      env["xray.location.asset"] = assets
      root["env"] = env
      guard let json = try? JSONSerialization.data(withJSONObject: root), let xrayJson = String(data: json, encoding: .utf8) else {
        return completionHandler(Self.error(3, "Invalid configuration"))
      }
      let result = Self.invoke("runXray", ["xrayJson": xrayJson])
      if !result.success { return completionHandler(Self.error(4, result.error)) }
      completionHandler(nil)
    }
  }

  override func stopTunnel(with reason: NEProviderStopReason, completionHandler: @escaping () -> Void) {
    _ = Self.invoke("stopXray", [:])
    completionHandler()
  }

  /// utun descriptor owned by this extension.
  private var tunnelFd: Int32? {
    var buf = [CChar](repeating: 0, count: Int(IFNAMSIZ))
    for fd: Int32 in 0...1024 {
      var len = socklen_t(buf.count)
      if getsockopt(fd, 2 /* SYSPROTO_CONTROL */, 2 /* UTUN_OPT_IFNAME */, &buf, &len) == 0, String(cString: buf).hasPrefix("utun") {
        return fd
      }
    }
    return nil
  }

  private static func invoke(_ method: String, _ payload: [String: Any]) -> (success: Bool, error: String) {
    let request: [String: Any] = ["apiVersion": 3, "method": method, "payload": payload]
    guard let data = try? JSONSerialization.data(withJSONObject: request), let text = String(data: data, encoding: .utf8) else {
      return (false, "Invalid request")
    }
    let response: String? = LibXrayInvoke(text)
    guard let response, let obj = try? JSONSerialization.jsonObject(with: Data(response.utf8)) as? [String: Any] else {
      return (false, "Xray returned an invalid response")
    }
    return (obj["success"] as? Bool ?? false, obj["error"] as? String ?? "Xray failed to start")
  }

  private static func error(_ code: Int, _ message: String) -> NSError {
    NSError(domain: "Sharrow", code: code, userInfo: [NSLocalizedDescriptionKey: message])
  }
}
